<?php require __DIR__.'/../config/database.php';if(!empty($_SESSION['admin_id'])){header('Location: dashboard.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$user=trim($_POST['username']??'');$pass=$_POST['password']??'';$s=$conn->prepare('SELECT id,name,username,password_hash FROM admins WHERE username=? LIMIT 1');$s->bind_param('s',$user);$s->execute();$admin=$s->get_result()->fetch_assoc();if($admin&&password_verify($pass,$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];$_SESSION['admin_name']=$admin['name'];header('Location: dashboard.php');exit;}$error='Username atau password salah.';}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login Admin — Nusindo Wisata</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="login-page"><section class="login-card"><a class="brand" href="../index.php"><span class="brand-mark">N</span>Nusindo Wisata.</a><div class="kicker" style="margin-top:30px">Area pengelola</div><h1>Selamat datang kembali.</h1><p class="muted">Masuk untuk mengelola pemesanan dan paket wisata.</p><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form method="post"><div class="field" style="margin:18px 0"><label>Username</label><input name="username" required autocomplete="username"></div><div class="field" style="margin:18px 0"><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div><button class="btn btn-primary" style="width:100%">Login ke Dashboard →</button></form><p class="muted" style="font-size:.82rem;margin-top:22px"><a href="../index.php">← Kembali ke website</a></p></section></body></html>
